cat > vite.config.ts <<'EOF'
import { fileURLToPath } from 'node:url';
import { defineConfig } from 'vite';
import react from '@vitejs/plugin-react';

export default defineConfig({
  plugins: [react()],
  resolve: {
    alias: [
      // @gravity-ui/page-constructor ships CSS with webpack-style `~pkg/...` imports.
      { find: /^~/, replacement: '' },
      // @gravity-ui/page-constructor imports Node's `url` in one browser utility; use the browser build.
      { find: /^url$/, replacement: fileURLToPath(new URL('./node_modules/url/url.js', import.meta.url)) },
    ],
  },
});
EOF
npm run build 2>&1 | grep -v -i "deprecat\|sass-lang\|@import\|╷\|╵\|│\|More info\|root stylesheet\|^\s*$" | tail -30

cat > src/__render_check.test.tsx <<'EOF'
import { renderToString } from 'react-dom/server';
import { ThemeProvider } from '@gravity-ui/uikit';
import { test, expect } from 'vitest';
import { App } from './App';

test('landing renders hero, three benefits and CTA', () => {
  const html = renderToString(
    <ThemeProvider theme="light">
      <App />
    </ThemeProvider>,
  );
  for (const s of [
    'Понятно, куда уходит время вашей команды',
    'Таймер в один клик',
    'Отчёты по командам и проектам',
    'Быстрый старт',
    'Начните учитывать время уже сегодня',
    'Начать работу',
  ]) {
    expect(html).toContain(s);
  }
  console.log('HTML_LENGTH', html.length, 'H1', (html.match(/<h1/g) || []).length, 'BUTTONS', (html.match(/<button|<a [^>]*class="[^"]*button/g) || []).length);
});
EOF
timeout 170000 npx vitest run src/__render_check.test.tsx 2>&1 | tail -40; rm -f src/__render_check.test.tsx; ls src

